#!/usr/bin/env bash
# CCTV news daily report, generated by Antigravity CLI (gemini-3.8-flash-high)
# using the shared cctv-news skill (same SKILL.md Kiro uses).
# Flow: make sure the archive is valid -> hand the model the archive facts and
# the registered topics -> generate -> validate with scripts/check-report.py.
# If the primary model fails, times out or returns an unusable report, retry
# once with a fallback model.
# Kiro cron runs this in no_agent mode and delivers stdout verbatim.
set -Eeuo pipefail
umask 077

SKILL_DIR="${CCTV_NEWS_SKILL_DIR:-/root/.kiro-hermes/skills/news/cctv-news}"
SYNC_DIR="${CCTV_NEWS_SYNC_DIR:-/opt/cctv-news-sync}"
AGY="${AGY_BIN:-/usr/local/bin/agy}"
BUN="${CCTV_NEWS_BUN_BIN:-/root/.bun/bin/bun}"
MODEL="${AGY_MODEL:-gemini-3.8-flash-high}"
FALLBACK_MODEL="${AGY_FALLBACK_MODEL:-claude-sonnet-4-6}"
PRIMARY_MIN=40
# Hermes kills cron scripts after 3600s by default; keep the whole run under 56 min.
BUDGET=3360
FALLBACK_MIN_SECS=600
ARCHIVE_ROUNDS=3
ARCHIVE_WAIT=300
WORK=/tmp/cctv-news-work
LOG="${CCTV_NEWS_LOG:-/root/.kiro-hermes/logs/agy-cctv-news.log}"
LOCK=/run/lock/agy-cctv-news.lock
mkdir -p "$(dirname "$LOG")"

exec 9>"$LOCK"
flock -n 9 || { echo "另一次生成正在进行，本次跳过。"; exit 0; }

log() { printf '%s %s\n' "$(date --iso-8601=seconds)" "$*" >>"$LOG"; }

DATE_ARG="${1:-}"
if [[ -n "$DATE_ARG" ]]; then
  [[ "$DATE_ARG" =~ ^[0-9]{8}$ ]] || { echo "日期参数格式应为 YYYYMMDD。"; exit 64; }
  TARGET="$DATE_ARG"
  ARCHIVE_ROUNDS=1
else
  H=$((10#$(TZ=Asia/Shanghai date +%H)))
  if (( H < 6 )); then TARGET="$(TZ=Asia/Shanghai date -d yesterday +%Y%m%d)"
  else TARGET="$(TZ=Asia/Shanghai date +%Y%m%d)"; fi
fi
PRETTY="$(TZ=Asia/Shanghai date -d "$TARGET" +'%Y年%m月%d日')"
START=$SECONDS
log "start target=$TARGET model=$MODEL fallback=$FALLBACK_MODEL"

cd "$SKILL_DIR"
mkdir -p "$WORK"
find "$WORK" -mindepth 1 -maxdepth 1 -type f -delete 2>/dev/null || true
OUT=$(mktemp); ERR=$(mktemp); CAND=$(mktemp --suffix=.md)
trap 'rm -f "$OUT" "$ERR" "$CAND"' EXIT

facts() { python3 scripts/check-report.py facts "$1" 2>/dev/null; }

# --- 1. Archive: reuse local copy, else the validated sync clone, else fetch from CCTV.
archive_ok() { facts "$TARGET" >/dev/null; }
ensure_archive() {
  local round updated=0
  for (( round = 1; round <= ARCHIVE_ROUNDS; round++ )); do
    archive_ok && break
    if [[ -s "$SYNC_DIR/news/$TARGET.md" ]]; then
      cp -f "$SYNC_DIR/news/$TARGET.md" "news/$TARGET.md" && updated=1
      log "archive copied from sync clone"
    fi
    if ! archive_ok && (( round == ARCHIVE_ROUNDS )); then
      log "archive fetch from cctv"
      timeout 240 "$BUN" scripts/manual-fetch.ts "$TARGET" >/dev/null 2>>"$LOG" || true
      updated=1
    fi
    archive_ok && break
    if (( round < ARCHIVE_ROUNDS )); then
      log "archive not ready, wait ${ARCHIVE_WAIT}s (round $round)"
      sleep "$ARCHIVE_WAIT"
    fi
  done
  if (( updated )) && archive_ok; then
    timeout 120 "$BUN" make-index.ts >/dev/null 2>&1 || log "make-index failed (ignored)"
  fi
  archive_ok
}

if ! ensure_archive; then
  log "archive unavailable target=$TARGET reason=$(facts "$TARGET" | head -1 || true)"
  LATEST=""; LINK=""
  for f in $(ls news | grep -E '^[0-9]{8}\.md$' | sort -r | head -10); do
    d="${f%.md}"
    [[ "$d" < "$TARGET" ]] || continue
    if LINK=$(facts "$d" | sed -n 's/^本期央视文字稿链接：\(http.*\)$/\1/p') && [[ -n "$LINK" ]]; then
      LATEST="$d"; break
    fi
  done
  echo "《新闻联播》${PRETTY}文字稿尚未就绪，日报稍后补发。"
  if [[ -n "$LATEST" ]]; then
    echo
    echo "最近可用：[$(TZ=Asia/Shanghai date -d "$LATEST" +'%m月%d日')文字稿]($LINK)"
  fi
  exit 0
fi

FACTS=$(facts "$TARGET")
TOPICS=$(python3 scripts/topics.py show --date "$TARGET" 2>/dev/null || echo "尚无登记记录")
log "archive ok stories=$(sed -n 's/^详细新闻条数：\([0-9]*\).*/\1/p' <<<"$FACTS")"

TASK=$(cat <<EOF
使用 cctv-news skill 生成 ${TARGET}（显示为 ${PRETTY}）的《新闻联播》完整富文本日报。
严格执行该 skill 的固定输出顺序、A股研判边界、链接规则与富文本排版规则。

工作目录：${SKILL_DIR}
当日归档 news/${TARGET}.md 已抓取并验证有效，直接读取，不要重新抓取，也不要访问 GitHub。

【归档事实清单】（程序统计，唯一口径，照抄不重数）
${FACTS}

【上一期登记的主线与热词】
${TOPICS}

补充要求：
1. 报告第一行必须严格是：# 《新闻联播》每日研判（${PRETTY}）
   只替换日期，其余文字、标点、格式不得改写。
2. 顶部数据状态行照抄事实清单里的固定写法。
3. 输出 3 至 5 条今日大事、0 至 4 条 A股当日增量信号（以 2 条以内为常态）、2 至 4 条滚动30日长期主线、4 个近10日热词。
   A股信号按 skill 的入选门槛筛选，没有清晰信号就写“当日无明显增量信号”，不得凑数；可信度“高”最多 1 条。
4. 长期主线和热词默认沿用上一期登记，名称逐字不改，每期最多各换 1 个。写报告前运行
   python3 scripts/topics.py set --date ${TARGET} ... 登记本期使用的主线和热词。
   热词表用 python3 scripts/trend-analysis.py 10 --until ${TARGET} ... 生成并原样放入。
5. 第五部分按事实清单的序号、标题、链接全部列出，标题原样保留，不重新分类、不省略。
6. 只使用归档文件内真实存在的 URL，缺失就不显示，严禁虚构。报告在第五部分结束，不输出"六、资料来源"。
7. 定稿前把草稿写到 ${WORK}/draft.md，运行
   python3 scripts/check-report.py check ${TARGET} ${WORK}/draft.md
   并修正全部 FATAL 和 ERROR，最多改两轮。不要自己编写任何校验或字数统计脚本，不要在工作目录里新建文件。

输出要求：
只输出最终报告正文本身。不要输出任何前言、结语、进度说明、自检结果、命令、抓取路径、目录、主播统计、内部推理或工具说明。第一个字符必须是 # 号。
EOF
)

REPORT=""
BEST=""

# generate MODEL MINUTES: on success REPORT holds a usable report and it returns 0.
generate() {
  local model=$1 mins=$2 rc=0 check_rc=0 check_out
  : >"$OUT"; : >"$ERR"
  log "run model=$model print_timeout=${mins}m"
  timeout $(( mins * 60 + 60 )) "$AGY" \
      --model "$model" \
      --dangerously-skip-permissions \
      --print-timeout "${mins}m" \
      -p "$TASK" >"$OUT" 2>"$ERR" || rc=$?
  if (( rc != 0 )); then
    log "agy failed model=$model rc=$rc stderr=$(tail -c 500 "$ERR" | tr '\n' ' ')"
    return 1
  fi
  if grep -Eq 'AGY_ERROR|DEADLINE_EXCEEDED|returning partial output' "$ERR"; then
    log "agy partial output model=$model stderr=$(tail -c 300 "$ERR" | tr '\n' ' ')"
    return 1
  fi
  # Drop agy progress chatter before the first markdown heading.
  REPORT=$(awk 'f{print; next} /^#[^#]/{f=1; print}' "$OUT")
  [[ -z "$REPORT" ]] && REPORT=$(cat "$OUT")
  REPORT=$(printf '%s' "$REPORT" | sed -E 's/\r$//')
  if [[ -z "${REPORT// }" ]]; then
    log "empty report model=$model stderr=$(tail -c 500 "$ERR" | tr '\n' ' ')"
    return 1
  fi
  printf '%s\n' "$REPORT" >"$CAND"
  check_out=$(python3 scripts/check-report.py check "$TARGET" "$CAND" 2>&1) || check_rc=$?
  log "check model=$model rc=$check_rc $(tail -n 1 <<<"$check_out")"
  if (( check_rc != 0 )); then
    grep -E '^(FATAL|ERROR)' <<<"$check_out" | head -12 | while IFS= read -r line; do log "  $line"; done
  fi
  if (( check_rc >= 2 )); then
    BEST="$REPORT"
    return 1
  fi
  log "success model=$model chars=${#REPORT}"
}

if ! generate "$MODEL" "$PRIMARY_MIN"; then
  LEFT=$(( BUDGET - (SECONDS - START) ))
  if (( LEFT >= FALLBACK_MIN_SECS )) && generate "$FALLBACK_MODEL" $(( (LEFT - 60) / 60 )); then
    :
  elif [[ -n "$BEST" ]]; then
    # Both runs had problems, but a complete-looking report beats a failure notice.
    log "delivering report that failed structure check"
    REPORT="$BEST"
  else
    (( LEFT < FALLBACK_MIN_SECS )) && log "no time left for fallback (left=${LEFT}s)"
    echo "《新闻联播》日报生成失败：主模型与备用模型均未成功，请稍后重试或查看 $LOG。"
    exit 1
  fi
fi

printf '%s\n' "$REPORT"
